snippet_css:
:root{
  --bg: #FFF7FA;
  --fg: #5B4636;
  --muted: #75665A;
  --surface: #FFFFFF;
  --border: #FFD9E6;
  --accent: #FF7FAE;
  --accent-fg: #4A3428;
  --accent-grad: linear-gradient(#FFB7C5,#FF7FAE);
  --radius: 26px;
  --radius-sm: 16px;
  --shadow: 0 10px 24px rgba(255,183,197,.42);
  --btn-shadow: 0 5px 0 #FF9EBB;
  --art-bg: radial-gradient(circle at 30% 25%,#FFF1A8,#FFB7C5);
  --media-bg: radial-gradient(circle at 30% 25%,#FFF1A8,#FFC9DD);
  --cta-bg: #FFE3EE;
  --input-bg: #FFF7FA;
  --ok: #B5EAD7;
  --warn: #FF7FAE;
  --font-display: "Mochiy Pop One","M PLUS Rounded 1c",sans-serif;
  --font-body: "M PLUS Rounded 1c","Noto Sans TC",sans-serif;
  --focus-ring: #FF0F67;
}

